t.script:

(function () {
    function toggleOption(wrapper) {
        var checkbox = wrapper.querySelector('.sat-option-input');
        var inputs = wrapper.querySelectorAll('.sat-extra-input');

        if (!checkbox) {
            return;
        }

        if (checkbox.checked) {
            wrapper.classList.add('is-active');
            inputs.forEach(function (input) {
                input.disabled = false;
            });
        } else {
            wrapper.classList.remove('is-active');
            inputs.forEach(function (input) {
                input.disabled = true;
                input.value = '';
            });
        }
    }

    document.querySelectorAll('.sat-option-wrapper').forEach(function (wrapper) {
        var checkbox = wrapper.querySelector('.sat-option-input');

        if (!checkbox) {
            return;
        }

        checkbox.addEventListener('change', function () {
            toggleOption(wrapper);
        });

        toggleOption(wrapper);
    });

    var fotosInput = document.getElementById('fotos');
    var previewGrid = document.getElementById('satPreviewGrid');

    if (fotosInput && previewGrid) {
        fotosInput.addEventListener('change', function () {
            previewGrid.innerHTML = '';

            var files = Array.prototype.slice.call(fotosInput.files || []);
            files.slice(0, 12).forEach(function (file) {
                if (!file.type || !file.type.match(/^image\//)) {
                    return;
                }

                var reader = new FileReader();

                reader.onload = function (event) {
                    var item = document.createElement('div');
                    item.className = 'sat-preview-item';

                    var img = document.createElement('img');
                    img.src = event.target.result;
                    img.alt = file.name || 'foto';

                    item.appendChild(img);
                    previewGrid.appendChild(item);
                };

                reader.readAsDataURL(file);
            });
        });
    }

    var form = document.getElementById('satDemoraForm');
    var submitBtn = document.getElementById('satSubmitBtn');

    if (form && submitBtn) {
        form.addEventListener('submit', function () {
            submitBtn.disabled = true;
            submitBtn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> Guardando...';
        });
    }
})();
